payload.arguments:
{"command": "cd /exercise/gigasecond && cat > gigasecond.h <<'EOF'
#if !defined(GIGASECOND_H)
#define GIGASECOND_H

#include <boost/date_time/posix_time/posix_time.hpp>

namespace gigasecond {

boost::posix_time::ptime advance(const boost::posix_time::ptime& time);

}  // namespace gigasecond

#endif // GIGASECOND_H
EOF
cat > gigasecond.cpp <<'EOF'
#include "gigasecond.h"

namespace gigasecond {

boost::posix_time::ptime advance(const boost::posix_time::ptime& time) {
    return time + boost::posix_time::seconds(1000000000);
}

}  // namespace gigasecond
EOF
printf '%s\n' '--- gigasecond.h ---' && nl -ba gigasecond.h && printf '%s\n' '--- gigasecond.cpp ---' && nl -ba gigasecond.cpp"}

